TEST(AssertionVerify, RS256HappyPath) {
    IntegrationClaims c; std::string err;
    ASSERT_TRUE(verifyIntegrationAssertion(RS256_ASSERTION, ISS, AUD, RSA_PUB_PEM, c, err, PAST)) << err;
    EXPECT_EQ(c.issuer, "acme-integration");
    EXPECT_EQ(c.subject, "alice@acme");
    EXPECT_EQ(c.tenant, "acme");
    EXPECT_EQ(c.scope, "files.read files.write");
    EXPECT_EQ(c.jti, "assert-0001");
    EXPECT_EQ(c.token_type, "delegated");
    EXPECT_EQ(c.expires_at, 2000000000L);
}

TEST(AssertionVerify, ES256HappyPath) {
    IntegrationClaims c; std::string err;
    ASSERT_TRUE(verifyIntegrationAssertion(ES256_ASSERTION, ISS, AUD, EC_PUB_PEM, c, err, PAST)) << err;
    EXPECT_EQ(c.subject, "alice@acme");
    EXPECT_EQ(c.tenant, "acme");
}

TEST(AssertionVerify, WrongKeyRejected) {
    IntegrationClaims c; std::string err;
    // Verify an RS256 assertion against the EC key (and vice versa) — must fail.
    EXPECT_FALSE(verifyIntegrationAssertion(RS256_ASSERTION, ISS, AUD, EC_PUB_PEM, c, err, PAST));
    EXPECT_FALSE(verifyIntegrationAssertion(ES256_ASSERTION, ISS, AUD, RSA_PUB_PEM, c, err, PAST));
}

TEST(AssertionVerify, TamperedPayloadRejected) {
    // Flip a character in the payload segment; the signature no longer matches.
    std::string t = RS256_ASSERTION;
    const size_t dot1 = t.find('.');
    t[dot1 + 5] = (t[dot1 + 5] == 'A' ? 'B' : 'A');
    IntegrationClaims c; std::string err;
    EXPECT_FALSE(verifyIntegrationAssertion(t, ISS, AUD, RSA_PUB_PEM, c, err, PAST));
}

TEST(AssertionVerify, IssuerMismatchRejected) {
    IntegrationClaims c; std::string err;
    EXPECT_FALSE(verifyIntegrationAssertion(RS256_ASSERTION, "other-integration", AUD, RSA_PUB_PEM, c, err, PAST));
    EXPECT_EQ(err, "assertion issuer mismatch");
}

TEST(AssertionVerify, AudienceMismatchRejected) {
    IntegrationClaims c; std::string err;
    EXPECT_FALSE(verifyIntegrationAssertion(RS256_ASSERTION, ISS, "https://evil.example.com", RSA_PUB_PEM, c, err, PAST));
    EXPECT_EQ(err, "assertion audience mismatch");
}

TEST(AssertionVerify, ExpiredRejected) {
    IntegrationClaims c; std::string err;
    // now well past exp (2000000000) + leeway.
    EXPECT_FALSE(verifyIntegrationAssertion(RS256_ASSERTION, ISS, AUD, RSA_PUB_PEM, c, err, 2000001000L));
    EXPECT_EQ(err, "assertion expired");
}

TEST(AssertionVerify, MalformedRejected) {
    IntegrationClaims c; std::string err;
    EXPECT_FALSE(verifyIntegrationAssertion("not-a-jwt", ISS, AUD, RSA_PUB_PEM, c, err, PAST));
    EXPECT_FALSE(verifyIntegrationAssertion("a.b", ISS, AUD, RSA_PUB_PEM, c, err, PAST));
}

TEST(AssertionVerify, NoneAlgRejected) {
    // alg:none header, empty signature — classic downgrade attack, must be refused.
    // header {"alg":"none","typ":"JWT"} . <same payload> .
    std::string none_hdr = "eyJhbGciOiJub25lIiwidHlwIjoiSldUIn0";
    std::string payload = std::string(RS256_ASSERTION);
    const size_t d1 = payload.find('.'), d2 = payload.find('.', d1 + 1);
    std::string body = payload.substr(d1 + 1, d2 - d1 - 1);
    std::string orig_sig = payload.substr(d2 + 1);
    // Keep a (now-meaningless) signature so the token is a well-formed 3-part JWT and
    // the alg:none guard — not the malformed check — is what rejects it.
    std::string forged = none_hdr + "." + body + "." + orig_sig;
    IntegrationClaims c; std::string err;
    EXPECT_FALSE(verifyIntegrationAssertion(forged, ISS, AUD, RSA_PUB_PEM, c, err, PAST));
    EXPECT_EQ(err, "unsupported assertion alg (expected RS256 or ES256)");
}

TEST(AssertionVerify, EmptyPemRejected) {
    IntegrationClaims c; std::string err;
    EXPECT_FALSE(verifyIntegrationAssertion(RS256_ASSERTION, ISS, AUD, "", c, err, PAST));
}

TEST(AssertionVerify, ExtractsAmrForTwoFactorTrust) {
    IntegrationClaims c; std::string err;
    ASSERT_TRUE(verifyIntegrationAssertion(AMR_ASSERTION, ISS, AUD, AMR_PUB_PEM, c, err, PAST)) << err;
    ASSERT_EQ(c.amr.size(), 2u);
    EXPECT_EQ(c.amr[0], "pwd");
    EXPECT_EQ(c.amr[1], "otp");   // a 2FA method -> propagates the integration's 2FA trust
}

TEST(AssertionVerify, AmrDefaultsEmptyWhenAbsent) {
    IntegrationClaims c; std::string err;
    ASSERT_TRUE(verifyIntegrationAssertion(RS256_ASSERTION, ISS, AUD, RSA_PUB_PEM, c, err, PAST)) << err;
    EXPECT_TRUE(c.amr.empty());
}
